result:
Confirmado: el patrón exacto ya existe en `AgentTool/UI.tsx` (`hasProgressMessage`) para el mismo problema — sólo que ahí `Progress` es una unión y aquí es `unknown`. Reutilizo el mismo tipo `AgentToolProgress` (misma forma real que construye `SkillTool.ts` en su `onProgress`) para angostar antes de pasar a `buildSubagentLookups`, sin tocar `progressTypes.ts`.

```json
{"file": "src/packages/tool-registry/src/tools/SkillTool/UI.tsx",
 "edits": [
   {"old": "import { buildSubagentLookups, EMPTY_LOOKUPS } from '@thyrox/agent/messages.js'
import { plural } from '@thyrox/output/utils/stringUtils.js'
import type { inputSchema, Output, Progress } from './SkillTool.js'",
    "new": "import { buildSubagentLookups, EMPTY_LOOKUPS } from '@thyrox/agent/messages.js'
import { plural } from '@thyrox/output/utils/stringUtils.js'
import type { inputSchema, Output, Progress } from './SkillTool.js'
import type { AgentToolProgress } from '../../progressTypes.js'"},
   {"old": "export function renderToolUseProgressMessage(",
    "new": "/**
 * Guarda: el progreso de SkillTool comparte forma con `AgentToolProgress`
 * (mensaje normalizado del subagente), pero su tipo declarado sigue siendo
 * `unknown` (`progressTypes.ts`). Angosta antes de pasarlo a
 * `buildSubagentLookups`.
 */
function hasProgressMessage(data: unknown): data is AgentToolProgress {
  if (typeof data !== 'object' || data === null) {
    return false
  }
  if (!('message' in data)) {
    return false
  }
  const msg = (data as AgentToolProgress).message
  return msg != null && typeof msg === 'object' && 'type' in msg
}

export function renderToolUseProgressMessage("},
   {"old": "  const hiddenCount = progressMessages.length - displayedMessages.length
  const { inProgressToolUseIDs } = buildSubagentLookups(
    progressMessages.map(pm => pm.data),
  )",
    "new": "  const hiddenCount = progressMessages.length - displayedMessages.length
  const { inProgressToolUseIDs } = buildSubagentLookups(
    progressMessages
      .filter((pm): pm is ProgressMessage<AgentToolProgress> =>
        hasProgressMessage(pm.data),
      )
      .map(pm => pm.data),
  )"}
 ],
 "patterns": [
   {"patron": "unknown-progress-data-into-buildSubagentLookups",
    "senal_del_verificador": "TS2345:.*not assignable to parameter of type '\{ message: AnyMessage;? ?\}(\[\])?'",
    "fix_generico": "Cuando `Progress` de una herramienta es el placeholder `unknown` (`progressTypes.ts`) y su dato real en tiempo de construcción trae un campo `message` normalizado, no se castea el arreglo entero: se define un guarda `data is AgentToolProgress` (o el tipo de progreso real, importado de `progressTypes.ts` sólo en lectura) que comprueba en runtime `typeof data === 'object' && data !== null && 'message' in data`, se usa como predicado de `.filter` sobre los `ProgressMessage<Progress>` y luego se mapea `pm => pm.data` ya angostado antes de pasarlo a `buildSubagentLookups`.",
    "edits": [0, 1, 2]}
 ],
 "fixes": ["src/packages/tool-registry/src/tools/SkillTool/UI.tsx(100,5): error TS2345: Argument of type 'unknown[]' is not assignable to parameter of type '{ message: AnyMessage; }[]'."],
 "skipped": []}
